H.background();
const a = P.a, b = P.b, c = P.c, d = P.d;
const parallel = Math.abs(a - c) <= 1e-6;
const xs = parallel ? 0 : (d - b) / (a - c);
const ys = a * xs + b;
// Adapt the window so the intersection (the whole point of the demo) stays
// visible even for shallow slope differences that push it far out.
const span = Math.max(8, Math.abs(xs) + 2, Math.abs(ys) + 2);
const v = H.plot2d({ xMin: -span, xMax: span, yMin: -span, yMax: span });
v.grid(); v.axes();
// left side y = a x + b, right side y = c x + d; solution where they meet
v.fn(x => a * x + b, { color: H.colors.accent, width: 3 });
v.fn(x => c * x + d, { color: H.colors.accent2, width: 3 });
H.text("Variables on both sides:  a·x + b = c·x + d", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
if (!parallel) {
  v.line(xs, -span, xs, ys, { color: H.colors.violet, width: 1.5, dash: [4, 4] });
  v.dot(xs, ys, { r: 7 + Math.sin(t * 3), fill: H.colors.good });
  v.text("x = " + xs.toFixed(2), xs + span * 0.03, ys + span * 0.08, { color: H.colors.good, size: 13 });
  H.text("collect x on one side: (a−c)·x = d−b   →   x = " + xs.toFixed(2), 24, 52, { color: H.colors.sub, size: 13 });
} else {
  H.text(Math.abs(b - d) < 1e-6 ? "same line — every x works (infinite solutions)" : "parallel — no x makes them equal (no solution)", 24, 52, { color: H.colors.warn, size: 13 });
}
// moving probe dot that sweeps along x, showing both sides' heights.
// Bound the sweep so BOTH heights stay inside the window at every frame.
const maxSlope = Math.max(Math.abs(a), Math.abs(c), 1e-6);
const xpAmp = Math.max(1, (span - Math.max(Math.abs(b), Math.abs(d)) - 1) / maxSlope);
const xp = Math.min(span - 2, xpAmp) * Math.sin(t * 0.6);
v.dot(xp, a * xp + b, { r: 5, fill: H.colors.accent });
v.dot(xp, c * xp + d, { r: 5, fill: H.colors.accent2 });
v.line(xp, a * xp + b, xp, c * xp + d, { color: H.colors.sub, width: 1, dash: [3, 3] });
H.legend([{ label: "left  a·x+b", color: H.colors.accent }, { label: "right  c·x+d", color: H.colors.accent2 }], H.W - 180, 28);
